result.text:
  }
  case "retry-job": {
    const job = ui.jobs.find((j) => j.id === id);
    if (job) {
      job.state = "queued";
      job.pct = 0;
      job.error = "";
      paintIngest();
      runQueue();
    }
    return;
  }
  case "acc-tab": {
    ui.conta.tab = id || "diario";
    render();
    return;
  }
  case "acc-all": {
    ui.conta.range = "all";
    ui.conta.from = "";
    ui.conta.to = "";
    render();
    return;
  }
  case "acc-apertura":
  case "acc-settings": {
    accAperturaModal();
    return;
  }
  case "acc-save-apertura": {
    saveApertura();
    return;
  }
  case "acc-entry-new": {
    accEntryModal(null);
    return;
  }
  case "acc-entry-edit": {
    accEntryModal(accManuales().find((a) => String(a.id) === String(id)) || null);
    return;
  }
  case "acc-entry-del": {
    deleteAccEntry(String(id || ""));
    return;
  }
  case "acc-entry-save": {
    saveAccEntry();
    return;
  }
  case "acc-entry-row": {
    accEntryAddRow();
    return;
  }
  case "acc-pdf-balance": {
    accPdfBalance();
    return;
  }
  case "acc-pdf-resultados": {
    accPdfResultados();
    return;
  }
  case "acc-own-new": {
    accOwnModal(null);
    return;
  }
  case "acc-own-edit": {
    const plan = accPlan();
    const todas = plan.subcuentas.concat(plan.propias);
    const cual = String(id || "");
    accOwnModal(todas.find((c) => String(c.code) === cual) || { code: cual, name: pgcNombre(cual) || "" });
    return;
  }
  case "acc-own-save": {
    saveAccOwn();
    return;
  }
  case "acc-plan-fix": {
    const plan = accPlan();
    updateSettings({ subcuentas: plan.subcuentas });
    toast(`${plan.subcuentas.length} subcuentas guardadas.`, "ok");
    render();
    return;
  }
  case "export-acc-csv": {
    exportAccCsv();
    return;
  }
  default:
    return;
}
